@@ -45,3 +45,12 @@ export function parseTasks(input: unknown): TaskSpec[] {
     return { id, dependsOn: [...dependsOn], priority };
   });
 }
+
+export function countByPriority(tasks: TaskSpec[]): Map<TaskSpec['priority'], number> {
+  const counts = new Map<TaskSpec['priority'], number>();
+  for (const task of tasks) {
+    const current = counts.get(task.priority) ?? 0;
+    counts.set(task.priority, current + 1);
+  }
+  return counts;
+}
